"""Aggregate audited numerical results. Keep runs, budgets and CAD distinct."""
import json,csv,sys,hashlib
from pathlib import Path
from build import STUDY,CP
OUT=STUDY/'results'

def main():
    plan=json.loads((OUT/'campaign-plan.json').read_text());extra=json.loads((OUT/'refinement-plan.json').read_text()) if (OUT/'refinement-plan.json').exists() else {'cases':[]};rows=[]
    for f in sorted(OUT.glob('*.json')):
        try:d=json.loads(f.read_text())
        except Exception:continue
        if isinstance(d,dict) and 'final' in d and 'inputs' in d and d.get('numerical_screens_pass') and 'range20to50' in d['final']['regions'] and all('best_sampled_5cm_mean_drop_k' in q for q in d['final']['sections']):rows.append(d)
    if not rows:raise RuntimeError('No audited CFD cases')
    best=[]
    for mass in [2,27,52,77]:
        options=[r for r in rows if r['inputs']['total_g_s']==mass and not r['case'].endswith('_laminar') and not r['case'].endswith('_fine')]
        if options:
            r=max(options,key=lambda x:x['final']['regions'].get('range20to50',x['final']['regions']['walking_corridor'])['6']['mass_kg']);best.append(r['case'])
    cols=['case','total_g_s','outlets','per_outlet_g_s','design','layout','width_m','height_m','exit_speed_m_s','hydraulic_reynolds','closure','cells','source_sensible_w','range_volume_ge6_m3','range_mass_ge6_g','whole_volume_ge6_m3','whole_mass_ge6_g','area_ge6_at20_m2','area_ge6_at35_m2','area_ge6_at50_m2','best_5cm_at20_drop_k','best_5cm_at35_drop_k','best_5cm_at50_drop_k','target_band_fluid_m3','mass_closure_relative','energy_closure_relative']
    with (OUT/'comparison.csv').open('w') as f:
        w=csv.DictWriter(f,fieldnames=cols,lineterminator='\n');w.writeheader()
        for r in rows:
            c=r['inputs'];v=r['final']['regions'].get('range20to50',r['final']['regions']['walking_corridor'])['6'];d=r['final']['regions']['domain']['6'];w.writerow({**{k:c[k] for k in cols if k in c},'case':r['case'],'source_sensible_w':r['source_cooling_w'],'range_volume_ge6_m3':v['volume_m3'],'range_mass_ge6_g':v['mass_kg']*1000,'whole_volume_ge6_m3':d['volume_m3'],'whole_mass_ge6_g':d['mass_kg']*1000,**{f'area_ge6_at{int(s["distance_m"]*100)}_m2':s['area_ge6_m2'] for s in r['final']['sections']},**{f'best_5cm_at{int(s["distance_m"]*100)}_drop_k':s.get('best_sampled_5cm_mean_drop_k') for s in r['final']['sections']},'target_band_fluid_m3':r.get('range_region',{}).get('fluid_volume_m3'),'mass_closure_relative':r['conservation']['mass_relative_error'],'energy_closure_relative':r['conservation']['energy_relative_error']})
    refined={}
    if (OUT/'refinement-status.json').exists():
        rs=json.loads((OUT/'refinement-status.json').read_text())
        for job in rs.get('selected',[]):
            if any(r['case']==job['name'] for r in rows):refined[str(job['mass_g'])]=job['name']
    cad=json.loads((STUDY/'cad/manifest.json').read_text()) if (STUDY/'cad/manifest.json').exists() else []
    validation=json.loads((OUT/'validation.json').read_text()) if (OUT/'validation.json').exists() else {}
    data=dict(grid_sensitivity=validation.get('grid_pairs',[]),representative_by_flow=refined,cad=cad,cases=rows,default_case=refined.get('77') or ('pilot_m77_n4_wide' if any(r['case']=='pilot_m77_n4_wide' for r in rows) else rows[0]['case']),best_coarse_by_flow=best,planned=plan['total_cases']+len(extra['cases']),completed=len(rows),source_c=plan['source_c'],ambient_c=30,spray_s=10,threshold_k=6,scope=plan['scope'])
    (OUT/'data.js').write_text('window.AA_SWEEP='+json.dumps(data,separators=(',',':'))+';')
    (OUT/'summary.json').write_text(json.dumps({k:v for k,v in data.items() if k!='cases'}|{'best_results':[next(r for r in rows if r['case']==name) for name in best],'selected_refined_results':[next(r for r in rows if r['case']==name) for name in refined.values()]},indent=2))
    def row(r):
        c=r['inputs'];v=r['final']['regions'].get('range20to50',r['final']['regions']['walking_corridor'])['6'];s=r['final']['sections'];return '<tr><td><button class="pick" data-case="'+r['case']+'">'+r['case']+'</button></td><td>'+str(c['total_g_s'])+'</td><td>'+str(c['outlets'])+'</td><td>'+f"{c['per_outlet_g_s']:.2f}"+'</td><td>'+f"{v['volume_m3']:.4f}"+'</td><td>'+f"{v['mass_kg']*1000:.1f}"+'</td>'+''.join('<td>'+f"{p['area_ge6_m2']:.4f}"+'</td>' for p in s)+''.join('<td>'+f"{p.get('best_sampled_5cm_mean_drop_k',0):.2f}"+'</td>' for p in s)+'</tr>'
    body=''.join(row(r) for r in sorted(rows,key=lambda x:(x['inputs']['total_g_s'],x['case'])))
    html='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>AA · Flow sweep CFD</title><style>
*{box-sizing:border-box}body{margin:0;background:#f1f5f6;color:#183542;font:15px/1.5 system-ui}main{max-width:1450px;margin:auto;padding:28px}a{color:#087f77}h1{font-size:34px;letter-spacing:-.03em;line-height:1.15}h2{font-size:19px;margin:0 0 14px}p{margin:8px 0 16px}.card{background:white;border:1px solid #d6e2e5;border-radius:9px;padding:22px;margin:18px 0;min-width:0}.two{display:grid;grid-template-columns:1fr 1fr;gap:18px}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.metrics>div{background:#fff;padding:16px;border:1px solid #d6e2e5;border-radius:7px}.metrics small{display:block;color:#5d747e;font-size:12px}.metrics b{font-size:23px;display:block;margin-top:6px}.note{font-size:12px;color:#607780}.banner{background:#e6f3ef;padding:14px 18px;border-left:3px solid #087f77}select,button{font:inherit;padding:8px;border:1px solid #c9d8dd;background:white;border-radius:5px;color:#153744}select{max-width:100%}.toolbar{display:flex;gap:18px;align-items:center;flex-wrap:wrap}canvas{display:block;width:100%}#volume{height:530px;touch-action:none;cursor:grab}#sections{height:300px}#history{height:220px}.table{overflow:auto}table{border-collapse:collapse;width:100%;font-size:12px}th,td{padding:9px;border-bottom:1px solid #d6e2e5;text-align:right;white-space:nowrap}th:first-child,td:first-child{text-align:left}button.pick{border:0;padding:0;color:#087f77;font-size:12px;cursor:pointer;text-decoration:underline}.links{display:flex;flex-wrap:wrap;gap:16px;font-size:13px}.legend{height:14px;background:linear-gradient(90deg,#3049bd,#eeeeec,#b50427);max-width:260px}.ticks{display:flex;justify-content:space-between;max-width:260px;font-size:11px}.mobile-only{display:none}.tag{font-size:11px;letter-spacing:.08em;color:#607780;font-weight:700}li{margin:8px 0}@media(max-width:750px){main{padding:16px}.two{grid-template-columns:1fr}.metrics{grid-template-columns:1fr 1fr}.metrics b{font-size:20px}.card{padding:16px}#volume{height:410px}.mobile-only{display:block}h1{font-size:28px}}button:focus-visible,select:focus-visible,a:focus-visible{outline:3px solid #8dc9bf}
</style></head><body><main><a href="../../../project-overview.html#mass-flow-sweep">← Project overview</a> · <a href="../../../../index.html">Numerical lab</a><p class="tag">AA / EXECUTED THREE-DIMENSIONAL CFD / 23 OCT 2026</p><h1>Flow, outlet area and nozzle configuration.</h1><p>2, 27, 52 and 77 g/s total. One, two or four outlets. Distances 20, 35 and 50 cm. Still air, gravity, 10-second spray.</p>
<div class="banner">COMPLETION_TEXT. Source fixed at 0.959°C; ambient 30°C. Results are prescribed-source delivery screens. No motor operating map, person or comfort claim.</div>
<article class="card"><div class="toolbar"><label>Total source flow <select id="flow"><option value="all">All flows</option><option value="2">2 g/s</option><option value="27">27 g/s</option><option value="52">52 g/s</option><option value="77">77 g/s</option></select></label><label>Audited case <select id="case"></select></label><a id="caseEvidence" href="#">Inputs, balances and field hashes ↗</a><a id="native" href="#">Native OpenFOAM archive ↓</a><a href="comparison.csv">Full comparison CSV ↓</a><a href="calculations.json">First-principles calculations ↗</a></div><p id="description" class="note"></p></article><div id="metrics" class="metrics"></div>
<article class="card"><h2>2D sections at 10 seconds</h2><p class="note">Native cell containing each requested plane. Vertical sections for side/opposed layouts; horizontal sections for overhead. Area metrics use the labelled sampling bounds. Best sampled 5×5 cm means use 10 mm centre increments at t=10 s. These different orientations are not equivalent body areas.</p><label class="mobile-only">Distance<select id="distance"><option value="0">20 cm</option><option value="1">35 cm</option><option value="2">50 cm</option></select></label><canvas id="sections" role="img" aria-label="Native CFD temperature sections at 20, 35 and 50 cm"></canvas><div class="legend"></div><div class="ticks"><span>1°C</span><span>15.5°C</span><span>30°C</span></div><p><a id="png2" href="#">Section image ↓</a></p></article>
<div class="two"><article class="card"><h2>3D cold air volume · temperature ≤24°C</h2><label>Display region<select id="volumeRegion"><option value="range">20–50 cm target band</option><option value="whole">Whole simulated domain</option></select></label><canvas id="volume" role="img" aria-label="Interactive three-dimensional threshold-cell cold air volume"></canvas><div class="links"><a id="png3" href="#">3D image ↓</a><a id="glb" href="#">Actual cold-cell mesh · GLB ↓</a></div><p class="note">Cyan is the boundary of native cells at least 6°C below ambient. In target-band mode, flat faces at 20/50 cm are analysis cuts, not a physical end to the jet. Grey blocks are outlets. Surface is grid-stepped and can be disconnected. Mesh volume is checked against the cell-volume sum.</p></article><article class="card"><h2>Cooled volume during the spray</h2><canvas id="history" role="img" aria-label="Native cooled volume time history"></canvas><p class="note">The chart uses the 20–50 cm target band. Side slab: x±0.8 m, y=−0.35…−0.05 m, z=1…1.7 m (0.336 m³). Opposed uses the union of both slabs (0.672 m³). Overhead: x±0.8 m, y±0.2 m, z=1.6…1.9 m (0.192 m³). These sample volumes differ by layout. Common corridor metrics remain in the JSON. Whole-domain volume can include cold air below body height. No post-shutoff decay is simulated.</p><h2>Refinement and CAD</h2><p>Two original equal-area exits: 140×80 and 280×40 mm. Compact exits use a 2:1 aspect ratio and area sized for 1.5 m/s at each flow and outlet count. This is a design hypothesis, not a global optimum.</p><p><a href="../cad/manifest.json">CAD verification and exact dimensions</a> · <a href="../README.md">Method, replay and limitations</a> · <a href="validation.json">Campaign validation record</a></p><div id="cadLinks" class="links"></div><div id="refinement"></div></article></div>
<article class="card"><h2>All executed cases</h2><p class="note">All figures below use a 6°C drop at t=10 s. Columns A20/A35/A50 give section area in m². Last columns give best sampled 5 cm mean drops in °C. Cooled mass includes entrained air. Click a case to inspect its fields.</p><div class="table"><table><thead><tr><th>Case</th><th>Total g/s</th><th>Outlets</th><th>g/s each</th><th>20–50 cm m³</th><th>20–50 cm g</th><th>A20 m²</th><th>A35 m²</th><th>A50 m²</th><th>5 cm Δ20</th><th>5 cm Δ35</th><th>5 cm Δ50</th></tr></thead><tbody>TABLE_BODY</tbody></table></div></article>
<footer class="note">Dry ideal-gas buoyant transient CFD. Reynolds number is a regime screen; jet transition depends on disturbances and inlet profile. Laminar/URANS and grid sensitivities do not establish a physical uncertainty bound. CAD exit dimensions match; nozzle interiors, mounting, manifold balance and pressure losses are not resolved.</footer></main><script src="data.js"></script><script src="viewer.js"></script><script>document.querySelectorAll('[data-case]').forEach(b=>b.onclick=()=>{AA_SweepViewer.selectCase(b.dataset.case);window.scrollTo({top:200,behavior:'smooth'});});</script></body></html>'''
    html=html.replace('TABLE_BODY',body).replace('COMPLETION_TEXT',f'{len(rows)} audited cases available')
    (OUT/'index.html').write_text(html)
    print(json.dumps(dict(completed=len(rows),best=best)))
if __name__=='__main__':main()
